$jm_notice = function_exists( 'wp_ja_morgan_form_notice' ) ? wp_ja_morgan_form_notice(
	array(
		'ok'             => __( 'Your account has been created. You can now log in.', 'wp-ja-morgan' ),
		'error-token'    => __( 'The form expired. Please try again.', 'wp-ja-morgan' ),
		'error-closed'   => __( 'Registration is closed on this site.', 'wp-ja-morgan' ),
		'error-fields'   => __( 'Please fill in every required field.', 'wp-ja-morgan' ),
		'error-password' => __( 'The two passwords do not match.', 'wp-ja-morgan' ),
		'error-tos'      => __( 'You must agree to the Terms of Service.', 'wp-ja-morgan' ),
		'error-exists'   => __( 'That username or email address is already in use.', 'wp-ja-morgan' ),
		'error-limit'    => __( 'Too many accounts were created from this connection. Please try again later.', 'wp-ja-morgan' ),
	)
) : '';
if ( ! get_option( 'users_can_register' ) ) :
	?>
<!-- wp:html {"metadata":{"name":"account.register-closed"}} -->
<div class="registration jm-form"><div class="alert alert-danger" role="status"><?php esc_html_e( 'Registration is closed on this site.', 'wp-ja-morgan' ); ?></div><p><a href="<?php echo esc_url( home_url( '/j-pages/login/' ) ); ?>"><?php esc_html_e( 'Log in', 'wp-ja-morgan' ); ?></a></p></div>
<!-- /wp:html -->
	<?php
	return;
endif;
?>
<!-- wp:html {"metadata":{"name":"account.register-form"}} -->
