n' ); ?></label></div></div></fieldset></div></div></fieldset><div class="form-group form-actions"><div class="jm-control"><button type="submit" class="btn btn-primary"><?php esc_html_e( 'Register', 'wp-ja-morgan' ); ?></button><a class="btn btn-default cancel" href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Cancel', 'wp-ja-morgan' ); ?></a></div></div></form></div>
